291	// SubmitReviewResult is the outcome of one submission attempt. Created is
292	// false when an identical submission (same ID and same field values) was
293	// retried: in that case Revision is the original revision and no new one is
294	// appended, even when the object was rejudged or withdrawn later.
295	type SubmitReviewResult struct {
296		Created   bool           `json:"created"`
297		ChainID   string         `json:"chainId"`
298		BlockHash string         `json:"blockHash"`
299		TxHash    string         `json:"txHash"`
300		Kind      string         `json:"kind"`
301		Status    string         `json:"status"`
302		Version   int            `json:"version"`
303		Revision  ReviewRevision `json:"revision"`
304	}
305	
306	// SubmitReview validates and stores one review revision. The target
307	// conclusion must exist in the archive. The first submission for an object
308	// must carry expectedVersion 0; every later one must carry the object's
309	// current version, otherwise the submission is rejected without touching
310	// stored data. Rejudgments and withdrawals append; older revisions stay.
311	// Identical retries (same archive-unique submission ID and identical
312	// fields) return the original revision. The whole update is one atomic
313	// commit under the archive lock, so concurrent submissions serialize and a
314	// stale concurrent submission can never overwrite another operator's
315	// revision.
316	func SubmitReview(dir string, sub ReviewSubmission) (SubmitReviewResult, error) {
317		if v := validateReviewSubmission(sub); v != nil {
318			return SubmitReviewResult{}, v.submitError()
319		}
320		if err := os.MkdirAll(dir, 0o755); err != nil {
321			return SubmitReviewResult{}, err
322		}
323		lock, err := lockArchive(dir, syscall.LOCK_EX|syscall.LOCK_NB)
324		if err != nil {
325			return SubmitReviewResult{}, err
326		}
327		defer lock.Close()
328	
329		data, err := readArchive(dir)
330		if err != nil {
331			return SubmitReviewResult{}, err
332		}
333		if _, _, ok := findArchivedConclusion(data, sub.key()); !ok {
334			return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s",
335				ErrUnknownConclusion, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind)
336		}
337	
338		// Submission IDs are unique archive-wide. An ID reuse with identical
339		// content is an idempotent retry of the original revision; it must
340		// succeed (and append nothing) even when the object has since moved on.
341		for i := range data.Reviews {
342			obj := &data.Reviews[i]
343			for _, rev := range obj.Revisions {
344				if rev.SubmissionID != sub.SubmissionID {
345					continue
346				}
347				existing := ReviewSubmission{
348					ChainID:         obj.ChainID,
349					BlockHash:       obj.BlockHash,
350					TxHash:          obj.TxHash,
351					Kind:            obj.Kind,
352					SubmissionID:    rev.SubmissionID,
353					Operator:        rev.Operator,
354					Reason:          rev.Reason,
355					Status:          rev.Status,
356					ExpectedVersion: rev.ExpectedVersion,
357				}
358				if !sub.contentEqual(existing) {
359					return SubmitReviewResult{}, fmt.Errorf("%w: %s", ErrSubmissionConflict, sub.SubmissionID)
360				}
361				return SubmitReviewResult{
362					Created:   false,
363					ChainID:   obj.ChainID,
364					BlockHash: obj.BlockHash,
365					TxHash:    obj.TxHash,
366					Kind:      obj.Kind,
367					Status:    currentReviewStatus(*obj),
368					Version:   len(obj.Revisions),
369					Revision:  rev,
370				}, nil
371			}
372		}
373	
374		idx := -1
375		for i := range data.Reviews {
376			if data.Reviews[i].key() == sub.key() {
377				idx = i
378				break
379			}
380		}
381		if idx >= 0 && data.Reviews[idx].Revisions == nil {
382			data.Reviews[idx].Revisions = []ReviewRevision{}
383		}
384		currentVersion := 0
385		if idx >= 0 {
386			currentVersion = len(data.Reviews[idx].Revisions)
387		}
388		if sub.ExpectedVersion != currentVersion {
389			return SubmitReviewResult{}, fmt.Errorf("%w: %s/%s tx %s %s is at version %d, submission expected %d",
390				ErrReviewConflict, sub.ChainID, sub.BlockHash, sub.TxHash, sub.Kind, currentVersion, sub.ExpectedVersion)
391		}
392		rev := sub.revision(currentVersion + 1)
393		if idx < 0 {
394			data.Reviews = append(data.Reviews, ReviewObject{
395				ChainID:   sub.ChainID,
396				BlockHash: sub.BlockHash,
397				TxHash:    sub.TxHash,
398				Kind:      sub.Kind,
399				Revisions: []ReviewRevision{rev},
400			})
401		} else {
402			data.Reviews[idx].Revisions = append(data.Reviews[idx].Revisions, rev)
403		}
404		if err := writeArchiveAtomic(dir, data); err != nil {
405			return SubmitReviewResult{}, err
406		}
407		return SubmitReviewResult{
408			Created:   true,
409			ChainID:   sub.ChainID,
410			BlockHash: sub.BlockHash,
411			TxHash:    sub.TxHash,
412			Kind:      sub.Kind,
413			Status:    sub.Status,
414			Version:   currentVersion + 1,
415			Revision:  rev,
416		}, nil
417	}
