551	// ReviewEvaluation is the false-positive analysis over one inclusive height
552	// range, judged consistently against one archive snapshot and its latest
553	// review state.
554	type ReviewEvaluation struct {
555		ChainID     string         `json:"chainId"`
556		StartHeight uint64         `json:"startHeight"`
557		EndHeight   uint64         `json:"endHeight"`
558		Version     RuleVersion    `json:"version"`
559		Retained    int            `json:"retained"`
560		Missed      int            `json:"missed"`
561		StillHit    int            `json:"stillHit"`
562		Eliminated  int            `json:"eliminated"`
563		Pending     int            `json:"pending"`
564		Details     []ReviewDetail `json:"details"`
565	}
566	
567	// sortReviewDetails orders by height, block hash, tx hash and kind.
568	func sortReviewDetails(details []ReviewDetail) {
569		sort.Slice(details, func(i, j int) bool {
570			a, b := details[i], details[j]
571			if a.BlockNumber != b.BlockNumber {
572				return a.BlockNumber < b.BlockNumber
573			}
574			if a.BlockHash != b.BlockHash {
575				return a.BlockHash < b.BlockHash
576			}
577			if a.TxHash != b.TxHash {
578				return a.TxHash < b.TxHash
579			}
580			return a.Kind < b.Kind
581		})
582	}
583	
584	// EvaluateReviews re-judges every archived block on chainID in the inclusive
585	// range [startHeight, endHeight] under the given registered rule version and
586	// compares the candidate conclusions against archived originals, using only
587	// archived evidence and the latest review state. Only original conclusions
588	// marked real or false positive feed the four counts: real risks split into
589	// retained (same tx and same kind still hits; severity changes do not
590	// matter) and missed; false positives split into still hit and eliminated.
591	// A candidate hit on the same tx and kind without a valid (non-withdrawn)
592	// review counts as pending, as does the new kind when the candidate changes
593	// a tx's conclusion type; withdrawn objects behave as unreviewed. The call
594	// is read-only: reports, the enabled version, reviews and alert records are
595	// never modified. An empty range yields zero counts and an empty list. The
596	// named candidate's stored document must still satisfy the registration
597	// rules in full — both rules declared with non-null, well-typed, in-range
598	// parameters, including a rule explicitly disabled (enabled:false) — or the
599	// whole evaluation fails with ErrCorruptVersion before any judgment, even
600	// when the range contains no blocks; the corrupt content is never replaced
601	// by defaults, the currently enabled version or the built-in rules. A
602	// corrupt version the call does not name never blocks an intact candidate.
603	func EvaluateReviews(dir, chainID string, startHeight, endHeight uint64, versionID string) (ReviewEvaluation, error) {
604		if strings.TrimSpace(chainID) == "" {
605			return ReviewEvaluation{}, errors.New("chainId must be a non-empty string")
606		}
607		if strings.TrimSpace(versionID) == "" {
608			return ReviewEvaluation{}, errors.New("version id must not be empty")
609		}
610		if startHeight > endHeight {
611			return ReviewEvaluation{}, fmt.Errorf("startHeight %d must not exceed endHeight %d", startHeight, endHeight)
612		}
613		result := ReviewEvaluation{
614			ChainID:     chainID,
615			StartHeight: startHeight,
616			EndHeight:   endHeight,
617			Details:     []ReviewDetail{},
618		}
619		if _, serr := os.Stat(dir); serr != nil {
620			if errors.Is(serr, os.ErrNotExist) {
621				// An absent archive has only the built-in version registered, so
622				// any other id is an unknown version even though the range would
623				// match no blocks.
624				if versionID != BuiltinVersionID {
625					return ReviewEvaluation{}, fmt.Errorf("%w: %s", ErrUnknownVersion, versionID)
626				}
627				result.Version = BuiltinVersion()
628				return result, nil
629			}
630			return ReviewEvaluation{}, serr
631		}
632		// One shared lock for the whole evaluation: the archive snapshot and the
633		// latest review state stay consistent across every block.
634		lock, err := lockArchive(dir, syscall.LOCK_SH)
635		if err != nil {
636			return ReviewEvaluation{}, err
637		}
638		defer lock.Close()
639	
640		// Decode with each registered version kept as its raw stored document,
641		// so a wrong-typed field in one version is that version's corruption,
642		// not whole-archive corruption, and the candidate's document can be
643		// re-validated from its bytes the same way a single-block comparison
644		// proves its version intact.
645		raw, err := readArchiveBytes(dir)
646		if err != nil {
647			return ReviewEvaluation{}, err
648		}
649		var doc rawVersionArchiveDoc
650		if len(raw) > 0 {
651			if err := json.Unmarshal(raw, &doc); err != nil {
652				return ReviewEvaluation{}, fmt.Errorf("archive is corrupted: %w", err)
653			}
654		}
655		// The requested version must be intact in the archive: re-validate its
656		// stored document before judging anything, so a corrupt version fails
657		// the same way even when the range matches no blocks, has no swaps or
658		// carries no valid manual review.
659		candidate, err := intactVersion(doc.Versions, versionID)
660		if err != nil {
661			return ReviewEvaluation{}, err
662		}
663		result.Version = candidate
664	
665		reviews := make(map[conclusionKey]*ReviewObject, len(doc.Reviews))
666		for i := range doc.Reviews {
667			reviews[doc.Reviews[i].key()] = &doc.Reviews[i]
668		}
669	
670		details := []ReviewDetail{}
671		for _, rec := range doc.Records {
672			if rec.ChainID != chainID {
673				continue
674			}
675			height := uint64(rec.BlockNumber)
676			if height < startHeight || height > endHeight {
677				continue
678			}
679			originalVersion := rec.ruleVersion()
680			candidateFindings := DetectBlockWithRules(rec.Swaps, candidate.Rules)
681			candByKey := make(map[conclusionKey]ReportFinding, len(candidateFindings))
682			candByTx := make(map[string]ReportFinding, len(candidateFindings))
683			for _, cf := range candidateFindings {
684				candByKey[conclusionKey{rec.ChainID, rec.BlockHash, cf.TxHash, cf.Kind}] = cf
685				candByTx[cf.TxHash] = cf
686			}
687	
688			// Original conclusions: only reviewed (real/false-positive) ones
689			// enter the four counts; same-kind candidate hits without a valid
690			// review are pending; originals that simply vanished without review
691			// are not counted anywhere.
692			for _, of := range rec.Findings {
693				key := conclusionKey{rec.ChainID, rec.BlockHash, of.TxHash, of.Kind}
694				obj := reviews[key]
695				original := &ReviewConclusion{Finding: of, Version: originalVersion}
696				if obj == nil || currentReviewStatus(*obj) == ReviewStatusUnreviewed {
697					if cf, ok := candByKey[key]; ok {
698						details = append(details, ReviewDetail{
699							ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
700							TxHash: of.TxHash, Kind: of.Kind, Bucket: BucketPending,
701							Original: original, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
702						})
703					}
704					continue
705				}
706				rev := obj.Revisions[len(obj.Revisions)-1]
707				detail := ReviewDetail{
708					ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
709					TxHash: of.TxHash, Kind: of.Kind, AppliedRevision: &rev, Original: original,
710				}
711				cf, hit := candByKey[key]
712				if hit {
713					detail.Candidate = &ReviewConclusion{Finding: cf, Version: candidate}
714				}
715				switch rev.Status {
716				case ReviewStatusReal:
717					if hit {
718						detail.Bucket = BucketRetained
719					} else {
720						detail.Bucket = BucketMissed
721					}
722				case ReviewStatusFalsePositive:
723					if hit {
724						detail.Bucket = BucketStillHit
725					} else {
726						detail.Bucket = BucketEliminated
727					}
728				}
729				details = append(details, detail)
730			}
731	
732			// Candidate conclusions whose (tx, kind) matches no original: when
733			// the same tx carried a different original kind this is the "new
734			// type" side of a type change; either way it is unreviewed and
735			// pending.
736			for _, cf := range candidateFindings {
737				if _, sameKind := findOriginalFinding(rec, cf.TxHash, cf.Kind); sameKind {
738					continue
739				}
740				details = append(details, ReviewDetail{
741					ChainID: rec.ChainID, BlockHash: rec.BlockHash, BlockNumber: rec.BlockNumber,
742					TxHash: cf.TxHash, Kind: cf.Kind, Bucket: BucketPending,
743					Original: nil, Candidate: &ReviewConclusion{Finding: cf, Version: candidate},
744				})
745			}
746		}
747	
748		for _, d := range details {
749			switch d.Bucket {
750			case BucketRetained:
751				result.Retained++
752			case BucketMissed:
753				result.Missed++
754			case BucketStillHit:
755				result.StillHit++
756			case BucketEliminated:
757				result.Eliminated++
758			case BucketPending:
759				result.Pending++
760			}
761		}
762		sortReviewDetails(details)
763		result.Details = details
764		return result, nil
765	}
766	
767	func findOriginalFinding(rec record, txHash, kind string) (ReportFinding, bool) {
768		for _, f := range rec.Findings {
769			if f.TxHash == txHash && f.Kind == kind {
