		evaluation, err := mevwatch.EvaluateReviews(args[1], args[2], start, end, args[5])
		if err != nil {
			fmt.Fprintf(os.Stderr, "reviews evaluate: %v\n", err)
			os.Exit(1)
		}
		writeJSON(evaluation)
	default:
		fmt.Fprintf(os.Stderr, "unknown reviews subcommand %q\n", args[0])
		usage()
		os.Exit(2)
	}
}

