553	// and a displacement hit under builtin) and registers a candidate whose
554	// stored document is about to be damaged: mult3 (multiplier 3) still flags
555	// the displacement 0xd (50 > 30), so the zero-multiplier corruption is one
556	// that previously sent detection into a divide-less but zeroed rule.
557	func setupReviewCorruptArchive(t *testing.T) string {
