565	// TestEvaluateCorruptVersionRefused runs the same corruption matrix the
566	// single-block comparison enforces against the review-range evaluation:
567	// every damaged candidate document fails the whole evaluation as a corrupt
568	// archived rule version, never as an unknown version, and the message names
569	// the requested version id and the offending rule or field.
570	func TestEvaluateCorruptVersionRefused(t *testing.T) {
571		for _, tc := range corruptVersionCases {
572			t.Run(tc.name, func(t *testing.T) {
573				dir := setupReviewCorruptArchive(t)
574				submit(t, dir, reviewSub("1", "0xa", "0xd", "displacement", "f", "a", "fp", ReviewStatusFalsePositive, 0))
