576					tc.mutate(t, ver)
577				})
578				_, err := EvaluateReviews(dir, "1", 0, 100, "mult3")
579				if err == nil {
580					t.Fatalf("corrupt version evaluated successfully")
581				}
582				if !errors.Is(err, ErrCorruptVersion) {
583					t.Fatalf("error = %v, want ErrCorruptVersion", err)
584				}
