586					t.Fatalf("corruption must not be reported as an unknown version: %v", err)
587				}
588				if !strings.Contains(err.Error(), "mult3") {
589					t.Fatalf("error must name the requested version, got %v", err)
590				}
591				if !strings.Contains(err.Error(), tc.wantErr) {
592					t.Fatalf("error must name the offending rule or field %q, got %v", tc.wantErr, err)
593				}
594			})
595		}
