643	// TestEvaluateCorruptVersionDistinctFromUnknown checks the boundary against
644	// unregistered ids, whole-archive corruption and intact siblings: an
645	// identifier that was never registered stays an unknown version, unreadable
646	// archive JSON stays archive corruption, and a damaged unselected version
647	// neither contaminates an intact candidate nor the built-in version.
648	func TestEvaluateCorruptVersionDistinctFromUnknown(t *testing.T) {
649		dir := setupReviewCorruptArchive(t)
650		submit(t, dir, reviewSub("1", "0xa", "0xd", "displacement", "f", "a", "fp", ReviewStatusFalsePositive, 0))
651		rewriteStoredVersion(t, dir, "mult3", func(ver map[string]any) {
652			delete(storedRule(t, ver, "displacement"), "multiplier")
653		})
654	
655		// Never registered: unknown version, not corruption.
656		if _, err := EvaluateReviews(dir, "1", 0, 100, "ghost"); !errors.Is(err, ErrUnknownVersion) ||
657			errors.Is(err, ErrCorruptVersion) {
658			t.Fatalf("unknown version error = %v", err)
659		}
660		// The built-in version is unaffected by the corrupt sibling.
661		got, err := EvaluateReviews(dir, "1", 0, 100, BuiltinVersionID)
662		if err != nil {
663			t.Fatalf("evaluate under builtin failed: %v", err)
664		}
665		if got.StillHit != 1 || got.Pending != 1 {
666			t.Fatalf("builtin evaluation counts = %+v", got)
667		}
668		if got.Version.ID != BuiltinVersionID {
669			t.Fatalf("candidate version = %+v", got.Version)
670		}
671	
672		// An intact second candidate still evaluates while the corrupt one sits
673		// unselected in the same archive.
674		mustRegisterVersion(t, dir, strictSpec)
675		strict, err := EvaluateReviews(dir, "1", 0, 100, "strict")
676		if err != nil {
677			t.Fatalf("evaluate under intact strict failed: %v", err)
678		}
679		// strict (mult 5) stops the displacement 0xd: the reviewed false
680		// positive is eliminated; the unreviewed sandwich still hits and is
681		// pending.
682		if strict.Eliminated != 1 || strict.Pending != 1 {
683			t.Fatalf("intact candidate counts = %+v", strict)
684		}
685	
686		// Unreadable archive JSON is whole-archive corruption regardless of the
687		// named version.
688		path := filepath.Join(dir, archiveFileName)
689		if err := os.WriteFile(path, []byte("{broken"), 0o644); err != nil {
690			t.Fatal(err)
691		}
692		if _, err := EvaluateReviews(dir, "1", 0, 100, BuiltinVersionID); err == nil ||
693			!strings.Contains(err.Error(), "archive is corrupted") {
694			t.Fatalf("unreadable archive error = %v, want archive corrupted", err)
695		}
696		if _, err := EvaluateReviews(dir, "1", 0, 100, "ghost"); err == nil ||
697			!strings.Contains(err.Error(), "archive is corrupted") {
698			t.Fatalf("unreadable archive must fail before version lookup: %v", err)
699		}
700	}
