808	// contenderStatuses gives each racing submitter a status of its own; the
809	// winner revision can then be proven to carry one submitter's complete
810	// content with no fields mixed in from another contender.
811	var contenderStatuses = []string{
812		ReviewStatusFalsePositive,
813		ReviewStatusReal,
814		ReviewStatusUnreviewed,
815	}
816	
817	func raceSub(i int) ReviewSubmission {
818		return reviewSub("1", "0xa", "0xv", "sandwich",
819			fmt.Sprintf("race-%02d", i),
820			fmt.Sprintf("operator-%02d", i),
821			fmt.Sprintf("reason-%02d", i),
822			contenderStatuses[i%len(contenderStatuses)], 1)
823	}
824	
825	type raceOutcome struct {
826		res SubmitReviewResult
827		err error
828	}
829	
830	// runRejudgmentRace fires n contenders carrying the same valid
831	// expectedVersion (1, against an object already at version 1) at the same
832	// instant, each with a distinct submissionId/operator/reason/status, and
833	// returns the per-submitter outcomes in submission order.
834	func runRejudgmentRace(t *testing.T, dir string, n int) []raceOutcome {
835		t.Helper()
836		outcomes := make([]raceOutcome, n)
837		var wg sync.WaitGroup
838		start := make(chan struct{})
839		for i := 0; i < n; i++ {
840			wg.Add(1)
841			go func(i int) {
842				defer wg.Done()
843				<-start
844				outcomes[i].res, outcomes[i].err = SubmitReview(dir, raceSub(i))
845			}(i)
846		}
847		close(start)
848		wg.Wait()
849		return outcomes
850	}
851	
852	// verifyRaceSettlement proves the anti-overwrite rules against the history
853	// actually persisted after a rejudgment race: exactly one contender created
854	// a revision, the object advanced exactly one version, every stored bit of
855	// the new revision comes from that winner alone, the original revision and
856	// the archived conclusion/evidence are untouched, and every loser (busy or
857	// version conflict) left no content behind.
858	func verifyRaceSettlement(t *testing.T, dir string, outcomes []raceOutcome, original ReviewRevision) int {
859		t.Helper()
860		winner := -1
861		busyIdx, conflictIdx := -1, -1
862		for i, o := range outcomes {
863			switch {
864			case o.err == nil:
865				if !o.res.Created || o.res.Version != 2 {
866					t.Fatalf("submitter %d returned %+v, want created at version 2", i, o.res)
867				}
868				if winner != -1 {
869					t.Fatalf("two successful contenders: %d and %d", winner, i)
870				}
871				winner = i
872			case errors.Is(o.err, ErrBusy):
873				// The contender hit the lock while another submitter held it.
874				busyIdx = i
875			case errors.Is(o.err, ErrReviewConflict):
876				// The contender entered after the lock was released, read the
877				// already-bumped version and was rejected on the version check.
878				conflictIdx = i
879			default:
880				t.Fatalf("submitter %d got an outcome other than success/busy/conflict: %v", i, o.err)
881			}
882		}
883		if winner == -1 {
884			t.Fatal("no contender succeeded")
885		}
886		t.Logf("race settled: winner=%d, busy=%d, version-conflict=%d (either loser outcome is valid)",
887			winner, countOutcomes(outcomes, ErrBusy), countOutcomes(outcomes, ErrReviewConflict))
888	
889		winSub := raceSub(winner)
890		wantRev := winSub.revision(2)
891		if !reflect.DeepEqual(outcomes[winner].res.Revision, wantRev) {
892			t.Fatalf("winner result revision = %+v, want %+v", outcomes[winner].res.Revision, wantRev)
893		}
894	
895		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
896		if err != nil {
897			t.Fatal(err)
898		}
899		if hist.Version != 2 || hist.Status != winSub.Status {
900			t.Fatalf("current state = %q/%d, want %q/2 (the winner's rejudgment)",
901				hist.Status, hist.Version, winSub.Status)
902		}
903		if len(hist.Revisions) != 2 {
904			t.Fatalf("object holds %d revisions, want exactly 2 (losers must leave none): %+v",
905				len(hist.Revisions), hist.Revisions)
906		}
907		if !reflect.DeepEqual(hist.Revisions[0], original) {
908			t.Fatalf("original revision not retained first: %+v, want %+v", hist.Revisions[0], original)
909		}
910		if !reflect.DeepEqual(hist.Revisions[1], wantRev) {
911			t.Fatalf("appended revision = %+v, want the winner's %+v", hist.Revisions[1], wantRev)
912		}
913		// Defense in depth: no field of any loser may appear in the new
914		// revision, and no loser submission id may be stored anywhere. Status is
915		// deliberately excluded because only three legal statuses exist so two
916		// contenders may legitimately carry the same one; identity/operator/
917		// reason are unique per submitter and the full-revision DeepEqual above
918		// already pins the winner's status.
919		loserIDs := map[string]bool{}
920		for i := range outcomes {
921			if i == winner {
922				continue
923			}
924			s := raceSub(i)
925			loserIDs[s.SubmissionID] = true
926			stored := hist.Revisions[1]
927			if stored.SubmissionID == s.SubmissionID || stored.Operator == s.Operator ||
928				stored.Reason == s.Reason {
929				t.Fatalf("loser %d content mixed into the stored revision: %+v", i, stored)
930			}
931			if reflect.DeepEqual(stored, s.revision(2)) {
932				t.Fatalf("stored revision is identical to loser %d's content: %+v", i, stored)
933			}
934		}
935		for _, rev := range hist.Revisions {
936			if loserIDs[rev.SubmissionID] {
937				t.Fatalf("loser submission id %q left a revision", rev.SubmissionID)
938			}
939		}
940		// The original archived conclusion, its detection parameters and the
941		// raw swap evidence stay exactly as archived.
942		if hist.Original == nil ||
943			hist.Original.Finding.TxHash != "0xv" || hist.Original.Finding.Kind != "sandwich" ||
944			hist.Original.Finding.Severity != 3 || len(hist.Original.Finding.Evidence) != 3 {
945			t.Fatalf("original conclusion/evidence changed: %+v", hist.Original)
946		}
947		if hist.Original.Version.ID != BuiltinVersionID {
948			t.Fatalf("detection version changed: %+v", hist.Original.Version)
949		}
950	
951		// After the race, resubmitting with the stale expected version must be a
952		// version conflict regardless of how the contender originally lost: a
953		// busy loss is not a completed rejudgment, and neither path may overwrite
954		// the winner.
955		recheck := func(idx int, label string) {
956			if idx < 0 {
957				return
958			}
959			if _, err := SubmitReview(dir, raceSub(idx)); !errors.Is(err, ErrReviewConflict) {
960				t.Fatalf("%s loser (submitter %d) replayed with original expected version: got %v, want ErrReviewConflict",
961					label, idx, err)
962			}
963		}
964		recheck(busyIdx, "busy")
965		recheck(conflictIdx, "conflict")
966		if _, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich", "late", "op", "r", ReviewStatusReal, 1)); !errors.Is(err, ErrReviewConflict) {
967			t.Fatalf("fresh follower with stale base: got %v, want ErrReviewConflict", err)
968		}
969	
970		// Deterministic late entrants: sequential submissions issued only after
971		// the object is provably at version 2 and the race lock is long released.
972		// Each acquires the free lock, reads the already-bumped version and must
973		// take the version-conflict path (never busy, since submissions are
974		// serialized here). This is the legitimate loser outcome the old
975		// regression assumed could never happen, and it must append nothing.
976		const lateN = 6
977		for j := 0; j < lateN; j++ {
978			_, err := SubmitReview(dir, reviewSub("1", "0xa", "0xv", "sandwich",
979				fmt.Sprintf("late-%02d", j),
980				fmt.Sprintf("late-operator-%02d", j),
981				fmt.Sprintf("late-reason-%02d", j),
982				contenderStatuses[j%len(contenderStatuses)], 1))
983			if !errors.Is(err, ErrReviewConflict) {
984				t.Fatalf("late entrant %d after lock release: got %v, want ErrReviewConflict", j, err)
985			}
986		}
987	
988		// The follow-up conflict submissions appended nothing either.
989		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
990		if err != nil {
991			t.Fatal(err)
992		}
993		if final.Version != 2 || len(final.Revisions) != 2 || !reflect.DeepEqual(final.Revisions, hist.Revisions) {
994			t.Fatalf("post-race conflict replays changed history: %+v", final)
995		}
996		return winner
997	}
