1009	func TestSubmitReviewConcurrentRejudgmentSettlesOnce(t *testing.T) {
1010		// Repeated races make the regression independent of scheduling: whether a
1011		// contender hits the held lock or enters after release and loses on the
1012		// version check, the settled history must be identical in shape. The loop
1013		// is deterministic (no timing assumptions): every contender starts from a
1014		// barrier and the settled state is derived from stored data, not from how
1015		// many contenders reported busy versus conflict.
1016		const racers, iterations = 12, 25
1017		for iter := 0; iter < iterations; iter++ {
1018			dir := t.TempDir()
1019			mustReplay(t, dir, twoFindingsInput)
1020			// An object that already carries one real risk judgment: the race is
1021			// a concurrent rejudgment at expectedVersion 1, not a first submit.
1022			first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-0", "alice", "first real call", ReviewStatusReal, 0))
1023			if !first.Created || first.Version != 1 {
1024				t.Fatalf("iter %d setup = %+v", iter, first)
1025			}
1026			outcomes := runRejudgmentRace(t, dir, racers)
1027			verifyRaceSettlement(t, dir, outcomes, first.Revision)
1028		}
1029	}
1030	
1031	// TestSubmitReviewBusyHoldsOffThenActualVersionDecides pins the two-phase
1032	// behavior deterministically (without relying on goroutine interleaving):
1033	// while the archive is occupied, a valid rejudgment returns busy and changes
1034	// nothing; once the lock is released the same submission is accepted or
1035	// rejected by the object's actual version, never because the busy attempt was
1036	// treated as a completed rejudgment.
1037	func TestSubmitReviewBusyHoldsOffThenActualVersionDecides(t *testing.T) {
1038		dir := t.TempDir()
1039		mustReplay(t, dir, twoFindingsInput)
1040		first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "hold-1", "alice", "confirmed bot war", ReviewStatusReal, 0))
1041		if !first.Created || first.Version != 1 {
1042			t.Fatalf("setup = %+v", first)
1043		}
1044		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1045		if err != nil {
1046			t.Fatal(err)
1047		}
1048	
1049		holder, err := os.OpenFile(filepath.Join(dir, lockFileName), os.O_CREATE|os.O_RDWR, 0o644)
1050		if err != nil {
1051			t.Fatal(err)
1052		}
1053		if err := syscall.Flock(int(holder.Fd()), syscall.LOCK_EX); err != nil {
1054			t.Fatal(err)
1055		}
1056	
1057		// A legal rejudgment based on version 1: while occupied it must report
1058		// busy and write nothing.
1059		contender := reviewSub("1", "0xa", "0xv", "sandwich", "hold-2", "bob", "second look says false positive", ReviewStatusFalsePositive, 1)
1060		res, err := SubmitReview(dir, contender)
1061		if !errors.Is(err, ErrBusy) {
1062			t.Fatalf("occupied archive: got %v, want ErrBusy", err)
1063		}
1064		if res.Created || res.Version != 0 || res.Revision != (ReviewRevision{}) {
1065			t.Fatalf("busy submission returned a non-empty result: %+v", res)
1066		}
1067		archiveDuring, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1068		if err != nil {
1069			t.Fatal(err)
1070		}
1071		if !reflect.DeepEqual(archiveBefore, archiveDuring) {
1072			t.Fatal("busy submission changed the archive while the lock was held")
1073		}
1074	
1075		// Release the occupation; existing review content must be intact.
1076		if err := syscall.Flock(int(holder.Fd()), syscall.LOCK_UN); err != nil {
1077			t.Fatal(err)
1078		}
1079		if err := holder.Close(); err != nil {
1080			t.Fatal(err)
1081		}
1082		held, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1083		if err != nil {
1084			t.Fatal(err)
1085		}
1086		if held.Status != ReviewStatusReal || held.Version != 1 || len(held.Revisions) != 1 {
1087			t.Fatalf("busy loss altered review content: %+v", held)
1088		}
1089		if !reflect.DeepEqual(held.Revisions[0], first.Revision) {
1090			t.Fatalf("original revision changed: %+v, want %+v", held.Revisions[0], first.Revision)
1091		}
1092	
1093		// Lock released but the object is still at version 1 (busy never
1094		// completed the rejudgment): the same submission with its original
1095		// expectedVersion 1 now succeeds as a fresh create — the busy attempt
1096		// neither consumed the submission id nor counted as a stored revision.
1097		retry, err := SubmitReview(dir, contender)
1098		if err != nil {
1099			t.Fatalf("retry after release: %v", err)
1100		}
1101		wantRev := contender.revision(2)
1102		if !retry.Created || retry.Version != 2 || !reflect.DeepEqual(retry.Revision, wantRev) {
1103			t.Fatalf("retry = %+v, want created at v2 with %+v", retry, wantRev)
1104		}
1105		hist, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1106		if err != nil {
1107			t.Fatal(err)
1108		}
1109		if hist.Status != ReviewStatusFalsePositive || hist.Version != 2 || len(hist.Revisions) != 2 {
1110			t.Fatalf("object after retry = %q/%d with %d revisions", hist.Status, hist.Version, len(hist.Revisions))
1111		}
1112		if !reflect.DeepEqual(hist.Revisions[0], first.Revision) || !reflect.DeepEqual(hist.Revisions[1], wantRev) {
1113			t.Fatalf("revisions after retry = %+v", hist.Revisions)
1114		}
1115	
1116		// Independently, if another rejudgment had committed while we waited,
1117		// releasing the lock would not make the stale submission succeed: with
1118		// the object now at version 2, a version-1 submission conflicts and
1119		// leaves no revision.
1120		late := reviewSub("1", "0xa", "0xv", "sandwich", "hold-3", "carol", "late arrival", ReviewStatusUnreviewed, 1)
1121		if _, err := SubmitReview(dir, late); !errors.Is(err, ErrReviewConflict) {
1122			t.Fatalf("stale submission after release: got %v, want ErrReviewConflict", err)
1123		}
1124		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1125		if err != nil {
1126			t.Fatal(err)
1127		}
1128		if after.Version != 2 || len(after.Revisions) != 2 || !reflect.DeepEqual(after.Revisions, hist.Revisions) {
1129			t.Fatalf("post-release conflict appended a revision: %+v", after)
1130		}
1131	}
