1133	func TestSubmitReviewFailureLeavesNoHalfRevision(t *testing.T) {
1134		dir := t.TempDir()
1135		mustReplay(t, dir, twoFindingsInput)
1136		before, err := os.ReadFile(filepath.Join(dir, archiveFileName))
