1174	func TestSubmitReviewSaveFailureRetriedAfterRecovery(t *testing.T) {
1175		dir := t.TempDir()
1176		mustReplay(t, dir, twoFindingsInput)
1177	
1178		// A pre-existing alert record must survive the failed and successful
1179		// submissions byte-for-byte in content.
1180		alertsBefore, err := GenerateAlerts(dir, "1", "ops", 0, 100, 1)
1181		if err != nil {
1182			t.Fatal(err)
1183		}
1184		if len(alertsBefore) != 2 {
1185			t.Fatalf("setup: got %d alert records, want 2", len(alertsBefore))
1186		}
1187	
1188		// Main precondition: the object is at version 1 with a real judgment and
1189		// one complete revision.
1190		first := submit(t, dir, reviewSub("1", "0xa", "0xv", "sandwich", "s-1", "alice", "confirmed bot", ReviewStatusReal, 0))
1191		if !first.Created || first.Version != 1 {
1192			t.Fatalf("setup submission = %+v", first)
1193		}
1194	
1195		original, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1196		if err != nil {
1197			t.Fatal(err)
1198		}
1199		if original.Status != ReviewStatusReal || original.Version != 1 || len(original.Revisions) != 1 {
1200			t.Fatalf("setup object state = %+v", original)
1201		}
1202		archiveBefore, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1203		if err != nil {
1204			t.Fatal(err)
1205		}
1206	
1207		// Valid target, valid content, valid expected version: the only failure
1208		// is storage failing while the new revision is being archived.
1209		breakArchiveSave(t, dir)
1210		rejudgment := reviewSub("1", "0xa", "0xv", "sandwich", "s-2", "bob", "actually a false positive", ReviewStatusFalsePositive, 1)
1211		failed, err := SubmitReview(dir, rejudgment)
1212		if err == nil {
1213			t.Fatalf("save failure must return an error, got result %+v", failed)
1214		}
1215		if errors.Is(err, ErrBusy) || errors.Is(err, ErrReviewConflict) ||
1216			errors.Is(err, ErrUnknownConclusion) || errors.Is(err, ErrSubmissionConflict) {
1217			t.Fatalf("failure must happen at the save stage, got %v", err)
1218		}
1219		if failed.Created {
1220			t.Fatalf("failed save must not report created=true: %+v", failed)
1221		}
1222		restoreArchiveSave(t, dir)
1223	
1224		// The original judgment is fully retained: still real at version 1, the
1225		// single original revision with no trace of the failed submission.
1226		after, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1227		if err != nil {
1228			t.Fatal(err)
1229		}
1230		if after.Status != ReviewStatusReal || after.Version != 1 {
1231			t.Fatalf("failed save advanced the object: %q/%d, want real/1", after.Status, after.Version)
1232		}
1233		if len(after.Revisions) != 1 {
1234			t.Fatalf("failed save left %d revisions: %+v", len(after.Revisions), after.Revisions)
1235		}
1236		if !reflect.DeepEqual(after.Revisions[0], original.Revisions[0]) {
1237			t.Fatalf("original revision changed: %+v, want %+v", after.Revisions[0], original.Revisions[0])
1238		}
1239		for _, rev := range after.Revisions {
1240			if rev.SubmissionID == "s-2" || rev.Operator == "bob" ||
1241				rev.Status == ReviewStatusFalsePositive || rev.Reason == "actually a false positive" {
1242				t.Fatalf("failed submission content leaked into history: %+v", rev)
1243			}
1244		}
1245		// The archived original conclusion, its detection version and the raw
1246		// swap evidence are untouched, as are the pre-existing alert records.
1247		if after.Original == nil ||
1248			after.Original.Finding.TxHash != "0xv" || after.Original.Finding.Kind != "sandwich" ||
1249			after.Original.Finding.Severity != 3 || len(after.Original.Finding.Evidence) != 3 {
1250			t.Fatalf("original conclusion/evidence changed: %+v", after.Original)
1251		}
1252		if after.Original.Version.ID != BuiltinVersionID {
1253			t.Fatalf("detection version changed: %+v", after.Original.Version)
1254		}
1255		archiveAfter, err := os.ReadFile(filepath.Join(dir, archiveFileName))
1256		if err != nil {
1257			t.Fatal(err)
1258		}
1259		if !reflect.DeepEqual(archiveBefore, archiveAfter) {
1260			t.Fatal("failed save modified the archive file")
1261		}
1262		alertsAfter, err := AlertHistory(dir, "1", "ops", 0, 100)
1263		if err != nil {
1264			t.Fatal(err)
1265		}
1266		if !reflect.DeepEqual(alertsBefore, alertsAfter) {
1267			t.Fatalf("alert records changed: before %+v after %+v", alertsBefore, alertsAfter)
1268		}
1269	
1270		// Storage recovered: the exact same submission, same submissionId and
1271		// still expectedVersion 1, goes through as a fresh create — the failed
1272		// attempt must neither have consumed the submission id nor count as a
1273		// stored duplicate.
1274		retry, err := SubmitReview(dir, rejudgment)
1275		if err != nil {
1276			t.Fatalf("retry after recovery: %v", err)
1277		}
1278		if !retry.Created || retry.Version != 2 || retry.Status != ReviewStatusFalsePositive {
1279			t.Fatalf("retry = %+v, want created=true at version 2", retry)
1280		}
1281		wantRev := rejudgment.revision(2)
1282		if !reflect.DeepEqual(retry.Revision, wantRev) {
1283			t.Fatalf("saved revision = %+v, want %+v", retry.Revision, wantRev)
1284		}
