1289		}
1290		if saved.Status != ReviewStatusFalsePositive || saved.Version != 2 || len(saved.Revisions) != 2 {
1291			t.Fatalf("object after retry = %q/%d with %d revisions", saved.Status, saved.Version, len(saved.Revisions))
1292		}
1293		if !reflect.DeepEqual(saved.Revisions[0], original.Revisions[0]) {
1294			t.Fatalf("original revision not retained first: %+v", saved.Revisions[0])
1295		}
1296		if !reflect.DeepEqual(saved.Revisions[1], wantRev) {
1297			t.Fatalf("appended revision = %+v, want %+v", saved.Revisions[1], wantRev)
1298		}
1299	
1300		// Sending the now-successful submission verbatim a second time is the
1301		// ordinary idempotent retry: created:false, the first successfully saved
1302		// revision returned, history unchanged.
1303		again, err := SubmitReview(dir, rejudgment)
1304		if err != nil {
1305			t.Fatalf("verbatim resend: %v", err)
1306		}
1307		if again.Created {
1308			t.Fatal("verbatim resend of a stored submission must report created=false")
1309		}
1310		if !reflect.DeepEqual(again.Revision, wantRev) || again.Version != 2 || again.Status != ReviewStatusFalsePositive {
1311			t.Fatalf("resend result = %+v", again)
1312		}
1313		final, err := ReviewHistoryQuery(dir, "1", "0xa", "0xv", "sandwich")
1314		if err != nil {
1315			t.Fatal(err)
1316		}
1317		if final.Version != 2 || len(final.Revisions) != 2 {
1318			t.Fatalf("verbatim resend changed history: version %d, %d revisions", final.Version, len(final.Revisions))
1319		}
1320		if !reflect.DeepEqual(final.Revisions, saved.Revisions) {
1321			t.Fatalf("verbatim resend appended a revision: %+v", final.Revisions)
1322		}
1323	}
